import React, { useEffect, useRef, useState } from 'react';
import { Linking, Platform, Pressable, ScrollView, Share, StyleSheet, Switch, Text, View, useWindowDimensions } from 'react-native';
import { api, date, money, operationKey, Page, patch, post, Product, Session, statuses } from './api';
import { Button, Empty, Field, Icon, Loading, Logo, Notice, ProductImage, Status } from './components';
import { C, S } from './theme';
import { AdminClaims } from './Claims';
import Analytics from './Analytics';
import Invitations from './Invitations';

type Props = { session: Session; onSwitch: () => Promise<void>; onLogout: () => Promise<void>; onNotice: (message: string) => void };
type Section = 'overview' | 'orders' | 'catalog' | 'merchants' | 'inventory' | 'audit';
type ManagedProduct = Product & { physicalStock?: number | null; onHand?: number | null; reserved?: number; quarantined?: number; savedPrice?: number | null; savedCaseSize?: number | null };

const nav: { id: Section; icon: string; label: string }[] = [
  { id: 'overview', icon: 'grid-outline', label: 'Vue d’ensemble' }, { id: 'orders', icon: 'receipt-outline', label: 'Demandes & commandes' },
  { id: 'catalog', icon: 'cube-outline', label: 'Catalogue & offres' }, { id: 'merchants', icon: 'storefront-outline', label: 'Commerçants' },
  { id: 'inventory', icon: 'layers-outline', label: 'Mouvements de stock' }, { id: 'audit', icon: 'shield-checkmark-outline', label: 'Journal d’activité' },
];
const captions: Record<Section, string> = { overview: 'Chaque demande, jusqu’à la livraison.', orders: 'Chiffrez, préparez et livrez depuis une seule file.', catalog: 'Des références réelles. Vos conditions commerciales.', merchants: 'Vos commerces partenaires et leurs accès.', inventory: 'Le détail de chaque entrée, réservation et retour.', audit: 'Les opérations de votre équipe, conservées dans le temps.' };
const int = (v: string, field: string, zero = false) => { const n = Number(v); if (!v.trim() || !Number.isSafeInteger(n) || n < (zero ? 0 : 1)) throw new Error(`${field} : saisissez un entier ${zero ? 'positif ou nul' : 'supérieur à zéro'}.`); return n; };
const amount = (v: string, field: string) => { const n = Number(v.replace(',', '.')); if (!v.trim() || !Number.isFinite(n) || n < 0 || Math.round(n * 100) / 100 !== n) throw new Error(`${field} : saisissez un montant valide avec deux décimales maximum.`); return n; };
const errText = (e: unknown) => e instanceof Error ? e.message : 'Cette action n’a pas abouti. Réessayez.';
function useRemote<T>(path: string | null, revision: number) {
  const [data, setData] = useState<T | null>(null), [loading, setLoading] = useState(false), [error, setError] = useState('');
  const generation = useRef(0);
  const previousPath = useRef(path);
  useEffect(() => { const g = ++generation.current; if (previousPath.current !== path) { setData(null); previousPath.current = path; } if (!path) { setData(null); setLoading(false); setError(''); return; } setLoading(true); setError(''); api<T>(path).then(x => { if (g === generation.current) setData(x); }).catch(e => { if (g === generation.current) setError(errText(e)); }).finally(() => { if (g === generation.current) setLoading(false); }); return () => { generation.current++; }; }, [path, revision]);
  return { data: previousPath.current === path ? data : null, loading, error };
}
function Chip({ children, active, onPress }: { children: React.ReactNode; active?: boolean; onPress: () => void }) {
  return <Pressable accessibilityRole="button" accessibilityState={{ selected: !!active }} onPress={onPress} style={({ pressed }) => [A.chip, { backgroundColor: active ? C.pale : C.white, borderColor: active ? C.green : C.border, opacity: pressed ? .7 : 1 }]}><Text style={[S.label, { color: active ? C.green : C.muted }]}>{children}</Text></Pressable>;
}
function Pagination({ value, change }: { value: Page<any> | null; change: (n: number) => void }) {
  if (!value || value.totalPages < 2) return null;
  return <View style={[S.between, { paddingVertical: 17, flexWrap: 'wrap' }]}><Text style={S.small}>{value.total} résultats · Page {value.page} sur {value.totalPages}</Text><View style={S.row}><Button icon="chevron-back" label="Page précédente" variant="secondary" disabled={value.page <= 1} onPress={() => change(value.page - 1)}>Précédent</Button><Button icon="chevron-forward" variant="secondary" disabled={value.page >= value.totalPages} onPress={() => change(value.page + 1)}>Suivant</Button></View></View>;
}
function SectionTitle({ title, detail, action }: { title: string; detail?: string; action?: React.ReactNode }) {
  return <View style={[S.between, { marginBottom: 20, flexWrap: 'wrap' }]}><View style={{ gap: 4, flexShrink: 1 }}><Text style={S.subheading}>{title}</Text>{detail ? <Text style={S.small}>{detail}</Text> : null}</View>{action}</View>;
}
function SummaryValue({ label, value, icon, positive: _positive = false }: { label: string; value: string | number; icon: string; positive?: boolean }) {
  return <View style={A.summaryValue}><View style={S.between}><Text style={S.muted}>{label}</Text><Icon name={icon} size={18} color={C.muted} /></View><Text style={A.metric}>{value}</Text></View>;
}
const actionLabels: Record<string, string> = { REQUESTED: 'Demande reçue', QUOTED: 'Devis envoyé', CONFIRMED: 'Commande confirmée', PREPARING: 'Préparation commencée', READY: 'Préparation terminée', OUT_FOR_DELIVERY: 'Départ en livraison', PAYMENT_COLLECTED: 'Encaissement déclaré', PAYMENT_RECONCILED: 'Encaissement rapproché', RETURN_INSPECTED: 'Retour contrôlé', PAYMENT_REFUNDED: 'Remboursement enregistré', OFFER_UPDATED: 'Offre mise à jour', STOCK_SET: 'Stock confirmé', ADJUSTED: 'Ajustement', RESERVED: 'Réservation', RELEASED: 'Réservation libérée', CLAIM_OPENED: 'Réclamation reçue', CLAIM_ACCEPTED: 'Réclamation acceptée', CLAIM_REJECTED: 'Réclamation refusée', CLAIM_RETURN_RECEIVED: 'Retour de réclamation reçu', CLAIM_RETURN_INSPECTED: 'Retour de réclamation contrôlé', COMMERCIAL_CREDIT_ISSUED: 'Avoir commercial accordé', DISPATCHED: 'Sortie de stock', SHIPPED: 'Sortie de stock', RESTOCK: 'Remise en stock', WRITE_OFF: 'Perte constatée' };

export default function Admin({ session, onSwitch, onLogout, onNotice }: Props) {
  const { width } = useWindowDimensions(), wide = width >= 1050;
  const [section, setSection] = useState<Section>('overview'), [revision, setRevision] = useState(0);
  const [query, setQuery] = useState(''), [search, setSearch] = useState(''), [status, setStatus] = useState(''), [page, setPage] = useState(1);
  const [orderId, setOrderId] = useState<string | null>(null), [product, setProduct] = useState<ManagedProduct | null>(null), [busy, setBusy] = useState(''), [actionError, setActionError] = useState('');
  const [csvOpen, setCsvOpen] = useState(false), [csv, setCsv] = useState('barcode,price,stock,caseSize,minimumQuantity,offerApproved\n');
  const endpoint = section === 'orders' ? 'orders' : section === 'catalog' ? 'products' : section;
  const list = useRemote<Page<any>>(section !== 'overview' && !orderId ? `/admin/${endpoint}?q=${encodeURIComponent(search)}&status=${status}&page=${page}&pageSize=${section === 'catalog' ? 20 : 15}` : null, revision);
  const detail = useRemote<any>(orderId ? `/orders/${orderId}` : null, revision);
  const refresh = () => setRevision(v => v + 1);
  const go = (next: Section, filter = '') => { setSection(next); setStatus(filter); setQuery(''); setSearch(''); setPage(1); setOrderId(null); setProduct(null); setActionError(''); setCsvOpen(false); };
  const run = async (key: string, task: () => Promise<unknown>, message: string) => { if (busy) return; setBusy(key); setActionError(''); try { await task(); onNotice(message); refresh(); } catch (e) { setActionError(errText(e)); } finally { setBusy(''); } };
  const openOrder = (id: string) => { setSection('orders'); setOrderId(id); setProduct(null); setActionError(''); };
  const filter = (next: string) => { setStatus(next); setPage(1); };
  const exportCsv = () => run('export', async () => { const value = await api<string>('/admin/export/orders'); if (Platform.OS === 'web' && (globalThis as any).document) { const d = (globalThis as any).document; const href = URL.createObjectURL(new Blob(['\uFEFF' + value], { type: 'text/csv;charset=utf-8;' })); const a = d.createElement('a'); a.href = href; a.download = 'Toushir_commandes.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(href), 1000); } else await Share.share({ message: value, title: 'Export des commandes Toushir' }); }, 'Export des commandes préparé.');
  const loading = orderId ? detail.loading : list.loading;
  const loadError = orderId ? detail.error : list.error;

  return <View style={[A.shell, { flexDirection: wide ? 'row' : 'column' }]}>
    {wide ? <View style={A.sidebar}>
      <View style={{ paddingHorizontal: 10 }}><Logo /><Text style={A.sidebarWorkspace}>{session.workspace.name}</Text></View>
      <View style={{ height: 30 }} />
      {nav.map(item => <Pressable key={item.id} accessibilityRole="button" accessibilityState={{ selected: section === item.id }} onPress={() => go(item.id)} style={({ pressed }) => [A.navItem, { backgroundColor: section === item.id ? C.pale : pressed ? C.bg : 'transparent' }]}>
        <Icon name={item.icon} size={19} color={section === item.id ? C.green : C.muted} />
        <Text style={[A.navText, { color: section === item.id ? C.green : C.muted }]}>{item.label}</Text>
        {section === item.id ? <View style={A.activeDot} /> : null}
      </Pressable>)}
      <View style={{ flex: 1, minHeight: 32 }} />
      <View style={A.sidebarBottom}><View style={A.avatar}><Text style={[S.label, { color: C.green }]}>{session.user.name.slice(0, 2).toUpperCase()}</Text></View><View style={{ flex: 1 }}><Text numberOfLines={1} style={S.label}>{session.user.name}</Text><Text style={S.small}>Grossiste · Oran</Text></View></View>
      {session.workspace.isDemo ? <Button onPress={() => run('switch', onSwitch, 'Espace commerçant ouvert.')} icon="phone-portrait-outline" variant="secondary" loading={busy === 'switch'}>App commerçant</Button> : null}
      <Button onPress={() => run('logout', onLogout, 'Session fermée.')} icon="log-out-outline" variant="ghost" style={{ marginTop: 8 }} loading={busy === 'logout'}>Se déconnecter</Button>
    </View> : <View style={A.mobileTop}>
      <View style={S.between}><Logo small /><View style={S.row}>{session.workspace.isDemo ? <Button label="Ouvrir l’application commerçant" icon="phone-portrait-outline" variant="secondary" onPress={() => run('switch', onSwitch, 'Espace commerçant ouvert.')} /> : null}<Button label="Se déconnecter" icon="log-out-outline" variant="ghost" onPress={() => run('logout', onLogout, 'Session fermée.')} /></View></View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8, paddingTop: 14 }}>{nav.map(item => <Chip key={item.id} active={section === item.id} onPress={() => go(item.id)}>{item.label}</Chip>)}</ScrollView>
    </View>}

    <ScrollView style={{ flex: 1 }} keyboardShouldPersistTaps="handled" contentContainerStyle={[A.content, { padding: wide ? 32 : 18 }]}>
      <View style={[S.between, { marginBottom: 24, flexWrap: 'wrap' }]}><View style={{ gap: 7, flexShrink: 1 }}><Text style={S.heading}>{orderId ? 'Détail de commande' : nav.find(x => x.id === section)?.label}</Text><Text style={S.muted}>{orderId ? 'Conditions, exécution et encaissement au même endroit.' : captions[section]}</Text></View>{section !== 'overview' ? <Button icon="refresh-outline" variant="secondary" loading={loading} onPress={refresh}>Actualiser</Button> : null}</View>
      {session.workspace.isDemo ? <View style={A.demoBanner}><Icon name="flask-outline" size={16} color={C.muted} /><Text style={[S.small, { flex: 1 }]}>Espace de test · Catalogue réel, commerces et opérations de test. Aucune vente ni aucun paiement externe.</Text><Button small variant="secondary" loading={busy==='demo-scenario'} disabled={!!busy} onPress={()=>run('demo-scenario',()=>post('/admin/demo/scenario'),'Exemples de travail chargés. Les montants et stocks de cet exemple sont fictifs.')}>Données d’exemple</Button></View> : null}
      {actionError ? <View style={{ marginBottom: 18 }}><Notice error>{actionError}</Notice></View> : null}
      {loadError ? <View style={{ gap: 12 }}><Notice error>{loadError}</Notice><Button icon="refresh-outline" onPress={refresh}>Réessayer</Button></View> : loading && !(orderId ? detail.data : list.data) ? <Loading count={3} /> : null}

      {section === 'overview' ? <Analytics key={revision} onOpenOrder={openOrder} onFilterOrders={(value: string) => go('orders', value)} onNotice={onNotice} /> : null}

      {section !== 'overview' && !orderId ? <View style={{ gap: 18 }}>
        {section !== 'orders' && section !== 'inventory' && section !== 'audit' ? <View style={[S.between, { flexWrap: 'wrap' }]}><View style={{ flex: 1, minWidth: 200 }}><Field label={section === 'catalog' ? 'Rechercher une référence' : section === 'merchants' ? 'Rechercher un commerce' : 'Rechercher une commande'} value={query} onChangeText={setQuery} onSubmitEditing={() => { setSearch(query); setPage(1); }} placeholder={section === 'catalog' ? 'Nom, marque ou code-barres…' : section === 'merchants' ? 'Boutique, nom, téléphone…' : 'Numéro, boutique, commerçant…'} returnKeyType="search" /></View><Button icon="search" variant="secondary" style={{ marginTop: 23 }} onPress={() => { setSearch(query); setPage(1); }}>Rechercher</Button>{section === 'catalog' ? <Button icon="cloud-upload-outline" variant="secondary" style={{ marginTop: 23 }} onPress={() => setCsvOpen(!csvOpen)}>Importer les offres</Button> : null}</View> : null}
        {section === 'merchants' && session.workspace.isDemo ? <Invitations onNotice={onNotice} ownerToken={session.workspaceToken}/> : null}
        {section === 'merchants' ? <View style={[S.row, { flexWrap: 'wrap' }]}>{[['', 'Tous les commerces'], ['PENDING', 'À approuver'], ['APPROVED', 'Approuvés'], ['SUSPENDED', 'Suspendus']].map(([v, label]) => <Chip key={v} active={status === v} onPress={() => filter(v)}>{label}</Chip>)}</View> : null}
        {csvOpen ? <View style={S.panel}><SectionTitle title="Importer vos conditions de vente" detail="Le fichier est validé en entier avant application. Les codes-barres doivent déjà exister dans le catalogue." action={<Button icon="close" label="Fermer l’import" variant="ghost" onPress={() => setCsvOpen(false)} />} /><Notice>Les prix et stocks doivent provenir de votre entreprise. Laissez les valeurs inconnues vides et offerApproved à false. Les montants CSV utilisent le point décimal.</Notice><View style={{ marginTop: 16 }}><Field label="Contenu du fichier CSV" value={csv} onChangeText={setCsv} multiline style={{ minHeight: 160, fontSize: 12 }} /></View><Button icon="checkmark-circle-outline" style={{ alignSelf: 'flex-start', marginTop: 16 }} loading={busy === 'import'} onPress={() => run('import', async () => { const r = await post<{ imported: number }>('/admin/catalog/import', { csv }); onNotice(`${r.imported} offres importées.`); setCsvOpen(false); }, 'Import validé et appliqué.')}>Valider et importer</Button></View> : null}
        {section === 'catalog' && product ? <ProductEditor key={product.id} product={product} busy={busy} onClose={() => setProduct(null)} onSave={body => run('product', async () => { const r = await patch<ManagedProduct>(`/admin/products/${product.id}`, body); setProduct(r); }, 'Conditions de vente enregistrées.')} onAdjust={body => run('adjust', async () => { const r = await post<ManagedProduct>('/admin/inventory/adjust', { ...body, productId: product.id }); setProduct(r); }, 'Ajustement de stock enregistré.')} reportError={setActionError} /> : null}
        <View style={S.panel}>{section === 'orders' ? <View style={{ gap: 18, marginBottom: 18 }}><View style={[S.between, { flexWrap: 'wrap', alignItems: 'flex-end' }]}><View style={{ flex: 1, minWidth: 200 }}><Field label="Rechercher une commande" value={query} onChangeText={setQuery} onSubmitEditing={() => { setSearch(query); setPage(1); }} placeholder="Numéro, commerce ou commerçant…" returnKeyType="search" /></View><OrderStatusFilter value={status} onChange={filter} /><Button icon="search" variant="secondary" onPress={() => { setSearch(query); setPage(1); }}>Rechercher</Button><Button icon="download-outline" variant="secondary" onPress={exportCsv} loading={busy === 'export'}>Exporter</Button></View><Text style={S.small}>{list.data?.total ?? 0} commande{list.data?.total === 1 ? '' : 's'}</Text></View> : <SectionTitle title={section === 'catalog' ? 'Références et conditions commerciales' : section === 'merchants' ? 'Commerces partenaires' : section === 'inventory' ? 'Mouvements de stock' : 'Journal des opérations'} detail={list.data ? `${list.data.total} ${section === 'catalog' ? 'références' : 'résultats'}` : undefined} />}
          {list.data?.items.length ? section === 'orders' ? <OrderTable rows={list.data.items} wide={wide} onOpen={openOrder} /> : section === 'catalog' ? list.data.items.map((p: ManagedProduct) => <Pressable key={p.id} accessibilityRole="button" accessibilityLabel={`Modifier les conditions de ${p.name}`} onPress={() => { setProduct(p); setActionError(''); }} style={({ pressed }) => [A.productRow, { backgroundColor: pressed ? C.pale : C.white }]}><ProductImage uri={p.imageUrl} name={p.name} size={64} /><View style={{ flex: 1, minWidth: 0, gap: 4 }}><Text style={S.label}>{p.brand || 'Marque non renseignée'}</Text><Text style={S.text} numberOfLines={2}>{p.name}</Text><Text style={S.small}>{p.barcode} · {p.category}</Text></View>{wide ? <View style={{ width: 135 }}><Text style={S.label}>{money(p.price)}</Text><Text style={S.small}>{p.stock == null ? 'Stock à confirmer' : `${p.stock} disponibles`}</Text></View> : null}<View style={{ alignItems: 'flex-end', gap: 5 }}><Text style={[S.small, { color: p.isActive === false ? C.red : p.offerApproved ? C.green : C.amber }]}>{p.isActive === false ? 'Suspendu' : p.offerApproved ? 'Offre approuvée' : 'Sur devis'}</Text><Icon name="create-outline" size={20} color={C.green} /></View></Pressable>) : section === 'merchants' ? list.data.items.map(m => <View key={m.id} style={[A.productRow, { flexWrap: 'wrap' }]}><View style={[A.avatar, { backgroundColor: C.pale }]}><Icon name="storefront-outline" color={C.green} /></View><View style={{ flex: 1, minWidth: 160, gap: 4 }}><Text style={S.label}>{m.shopName || m.name}</Text><Text style={S.small}>{m.name} · {m.phone || m.email}</Text><Text style={S.small}>{m.orderCount} commandes · {money(m.totalSpent)} livrés</Text></View><Status value={m.approvalStatus} /><View style={[S.row, { flexWrap: 'wrap' }]}>{m.approvalStatus !== 'APPROVED' ? <Button small variant="secondary" loading={busy === m.id} onPress={() => run(m.id, () => patch(`/admin/merchants/${m.id}`, { approvalStatus: 'APPROVED' }), 'Commerce approuvé.')}>Approuver</Button> : <Button small variant="danger" loading={busy === m.id} onPress={() => run(m.id, () => patch(`/admin/merchants/${m.id}`, { approvalStatus: 'SUSPENDED' }), 'Commerce suspendu.')}>Suspendre</Button>}</View></View>) : list.data.items.map(e => <View key={e.id} style={A.ledgerRow}><View style={{ flex: 1, gap: 4 }}><Text style={S.label}>{actionLabels[e.action || e.kind] || e.action || e.kind}</Text><Text style={S.muted}>{e.details || e.reason || 'Opération enregistrée'}</Text><Text style={S.small}>{e.actor} · {date(e.at, true)}</Text>{section === 'inventory' ? <Text style={S.small}>Référence {e.productId} {e.orderId ? `· Commande ${e.orderId.slice(0, 8)}` : ''}</Text> : null}</View>{section === 'inventory' ? <View style={{ alignItems: 'flex-end', gap: 4 }}><Text style={[S.label, { color: e.delta < 0 ? C.red : C.green }]}>{e.delta > 0 ? '+' : ''}{e.delta} physique</Text><Text style={S.small}>{e.reservedDelta > 0 ? '+' : ''}{e.reservedDelta} réservé</Text><Text style={S.small}>{e.quarantineDelta > 0 ? '+' : ''}{e.quarantineDelta} quarantaine</Text></View> : null}</View>) : !loading && !loadError ? <Empty title={section === 'catalog' ? 'Aucune référence trouvée' : section === 'merchants' ? 'Aucun commerce dans cette vue' : section === 'orders' ? 'Votre file est à jour' : 'Aucun mouvement pour le moment'} message={section === 'catalog' ? 'Essayez un nom plus court, une marque ou un code-barres.' : section === 'orders' ? 'Les nouvelles demandes apparaîtront ici. Changez de filtre pour retrouver les autres commandes.' : 'Les opérations apparaîtront automatiquement dès leur enregistrement.'} /> : null}
        {section === 'orders' ? <Pagination value={list.data} change={setPage} /> : null}</View>{section !== 'orders' ? <Pagination value={list.data} change={setPage} /> : null}
      </View> : null}
      {orderId && detail.data ? <OrderDetail key={orderId} order={detail.data} busy={busy} run={run} onBack={() => { setOrderId(null); setActionError(''); }} reportError={setActionError} /> : null}
      <Text style={[S.small, { marginTop: 30, textAlign: 'center' }]}>Toushir Gros · Oran · Les dates sont affichées en heure d’Algérie</Text>
    </ScrollView>
  </View>;
}

const orderFilters = [['', 'Tous les états'], ['REQUESTED', 'À chiffrer'], ['QUOTED', 'Devis envoyés'], ['SUBMITTED', 'Nouvelles'], ['CONFIRMED', 'Confirmées'], ['PREPARING', 'En préparation'], ['READY', 'Prêtes'], ['OUT_FOR_DELIVERY', 'En livraison'], ['DELIVERED', 'Livrées'], ['PARTIALLY_DELIVERED', 'Partiellement livrées'], ['DELIVERY_REFUSED', 'Livraison refusée'], ['CANCELLED', 'Annulées'], ['REJECTED', 'Refusées']];
function OrderStatusFilter({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  if (Platform.OS === 'web') return <View style={{ gap: 7, minWidth: 165 }}><Text style={S.label}>État</Text>{React.createElement('select', { 'aria-label': 'Filtrer les commandes par état', value, onChange: (event: React.ChangeEvent<HTMLSelectElement>) => onChange(event.target.value), style: { height: 48, border: `1px solid ${C.border}`, borderRadius: 9, background: C.white, color: C.ink, fontFamily: 'Inter, sans-serif', fontSize: 13, padding: '0 12px', cursor: 'pointer' } }, orderFilters.map(([key, label]) => React.createElement('option', { key, value: key }, label)))}</View>;
  return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8 }}>{orderFilters.map(([key, label]) => <Chip key={key} active={value === key} onPress={() => onChange(key)}>{label}</Chip>)}</ScrollView>;
}
function OrderTable({ rows, wide, onOpen }: { rows: any[]; wide: boolean; onOpen: (id: string) => void }) {
  if (!wide) return <View>{rows.map(order => <Pressable key={order.id} accessibilityRole="button" accessibilityLabel={`Ouvrir ${order.number}`} onPress={() => onOpen(order.id)} style={({ pressed }) => [A.orderRow, { backgroundColor: pressed ? C.pale : C.white }]}><View style={{ flex: 1, minWidth: 0, gap: 7 }}><Text numberOfLines={1} style={S.label}>{order.merchant?.shopName || 'Commerce'}</Text><Text style={S.small}>{order.number} · {date(order.createdAt)}</Text><View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6 }}><Status value={order.status} /><Status value={order.paymentStatus} /></View></View><View style={{ alignItems: 'flex-end', gap: 7 }}><Text style={S.label}>{money(order.total)}</Text><Text style={S.small}>{order.itemCount ?? 0} références</Text><Icon name="chevron-forward" size={18} color={C.muted} /></View></Pressable>)}</View>;
  return <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={{ minWidth: '100%' }}><View style={{ minWidth: 990, flex: 1 }}>
    <View style={A.tableHeader}><Text style={[A.tableLabel, A.cellMerchant]}>Commerce</Text><Text style={[A.tableLabel, A.cellNumber]}>Commande</Text><Text style={[A.tableLabel, A.cellDate]}>Date</Text><Text style={[A.tableLabel, A.cellAmount]}>Montant</Text><Text style={[A.tableLabel, A.cellStatus]}>État</Text><Text style={[A.tableLabel, A.cellPayment]}>Paiement</Text><Text style={[A.tableLabel, A.cellAction]}>Action</Text></View>
    {rows.map(order => <Pressable key={order.id} accessibilityRole="button" accessibilityLabel={`Ouvrir ${order.number}, ${order.merchant?.shopName || 'Commerce'}`} onPress={() => onOpen(order.id)} style={({ pressed }) => [A.tableRow, { backgroundColor: pressed ? C.pale : C.white }]}>
      <View style={A.cellMerchant}><Text numberOfLines={1} style={S.label}>{order.merchant?.shopName || 'Commerce'}</Text><Text numberOfLines={1} style={S.small}>{order.merchant?.name || ''}</Text></View>
      <View style={A.cellNumber}><Text numberOfLines={1} style={S.small}>{order.number}</Text><Text style={S.small}>{order.itemCount ?? 0} références</Text></View><Text style={[S.small, A.cellDate]}>{date(order.createdAt)}</Text><Text style={[S.label, A.cellAmount]}>{money(order.total)}</Text><View style={A.cellStatus}><Status value={order.status} /></View><View style={A.cellPayment}><Status value={order.paymentStatus} /></View><View style={A.cellAction}><Text style={[S.small, { color: C.green }]}>Voir</Text><Icon name="chevron-forward" size={15} color={C.muted} /></View>
    </Pressable>)}
  </View></ScrollView>;
}

type Run = (key: string, task: () => Promise<unknown>, message: string) => Promise<void>;
function OrderDetail({ order: o, busy, run, onBack, reportError }: { order: any; busy: string; run: Run; onBack: () => void; reportError: (message: string) => void }) {
  const { width } = useWindowDimensions(), wide = width >= 850;
  const [tab, setTab] = useState('process'), [reason, setReason] = useState(''), [confirmAction, setConfirmAction] = useState('');
  const [payment, setPayment] = useState(''), [method, setMethod] = useState('CASH'), [reference, setReference] = useState('');
  const [refund, setRefund] = useState(''), [refundRef, setRefundRef] = useState(''), [refundReason, setRefundReason] = useState('');
  const paymentKey = useRef(operationKey()), refundKey = useRef(operationKey());
  useEffect(() => { paymentKey.current = operationKey(); }, [payment, method, reference]);
  useEffect(() => { refundKey.current = operationKey(); }, [refund, refundRef, refundReason]);
  const transition: Record<string, [string, string]> = { SUBMITTED: ['CONFIRMED', 'Confirmer la commande'], CONFIRMED: ['PREPARING', 'Commencer la préparation'], PREPARING: ['READY', 'Marquer prête à partir'], READY: ['OUT_FOR_DELIVERY', 'Démarrer la livraison'] };
  const next = transition[o.status];
  return <View style={{ gap: 20 }}><Button icon="arrow-back" variant="ghost" style={{ alignSelf: 'flex-start', paddingLeft: 0 }} onPress={onBack}>Retour aux commandes</Button><View style={[S.panel, { gap: 18 }]}><View style={[S.between, { flexWrap: 'wrap' }]}><View style={{ gap: 5 }}><Text style={S.subheading}>{o.number}</Text><Text style={S.muted}>{o.merchant.shopName} · {date(o.createdAt, true)}</Text></View><View style={[S.row, { flexWrap: 'wrap' }]}><Status value={o.status} /><Status value={o.paymentStatus} /></View></View><View style={S.divider} /><View style={{ flexDirection: wide ? 'row' : 'column', gap: 24 }}><View style={{ flex: 1 }}><Text style={S.label}>Adresse de livraison</Text><Text style={S.text}>{o.address.street}</Text><Text style={S.muted}>{o.address.commune}, {o.address.wilaya}</Text><Text style={S.small}>{o.merchant.name}{o.merchant.phone ? ` · ${o.merchant.phone}` : ''}</Text></View><View style={{ flex: 1 }}><Text style={S.label}>Note du commerçant</Text><Text style={S.muted}>{o.note || 'Aucune instruction particulière.'}</Text>{o.quoteValidUntil ? <Text style={[S.small, { marginTop: 8 }]}>Devis v{o.quoteVersion} valable jusqu’au {date(o.quoteValidUntil, true)}</Text> : null}</View><View style={{ alignItems: wide ? 'flex-end' : 'flex-start' }}><Text style={S.small}>Montant contractuel</Text><Text style={A.metric}>{money(o.total)}</Text><Text style={S.small}>{o.reservationHeld ? 'Stock réservé' : 'Aucune réservation active'}</Text></View></View></View>
    <View style={[S.row, { flexWrap: 'wrap' }]}>{[['process', 'Traitement'], ['payments', 'Encaissements'], ...((o.claims?.length || o.creditTotal > 0) ? [['claims', `Réclamations (${o.claims?.length || 0})`]] : []), ['history', 'Historique']].map(([v, label]) => <Chip key={v} active={tab === v} onPress={() => setTab(v)}>{label}</Chip>)}</View>
    {tab === 'process' ? <>
      {['REQUESTED', 'QUOTED'].includes(o.status) ? <QuoteEditor order={o} busy={busy} run={run} reportError={reportError} /> : <View style={S.panel}><SectionTitle title="Produits de la commande" detail="Les conditions acceptées sont figées dans la commande." />{o.items.map((l: any) => <View key={l.id} style={A.productRow}><ProductImage uri={l.imageUrl} name={l.name} size={54} /><View style={{ flex: 1, gap: 3 }}><Text style={S.text}>{l.name}</Text><Text style={S.small}>{l.brand} · {l.quantity} unités {l.caseSize > 1 ? `· Colis de ${l.caseSize}` : ''}</Text>{['DELIVERED', 'PARTIALLY_DELIVERED', 'DELIVERY_REFUSED'].includes(o.status) ? <Text style={S.small}>{l.acceptedQuantity} acceptées · {l.refusedQuantity} refusées</Text> : null}</View><View style={{ alignItems: 'flex-end' }}><Text style={S.label}>{money(l.lineTotal)}</Text><Text style={S.small}>{money(l.unitPrice)} / unité</Text></View></View>)}<View style={[S.between, { marginTop: 18 }]}><Text style={S.muted}>Frais de livraison</Text><Text style={S.label}>{money(o.deliveryFee)}</Text></View></View>}
      {next ? <View style={[S.panel, S.between, { flexWrap: 'wrap' }]}><View style={{ flex: 1, minWidth: 180 }}><Text style={S.subheading}>L’étape suivante</Text><Text style={[S.muted, { marginTop: 4 }]}>{next[0] === 'OUT_FOR_DELIVERY' ? 'Confirmez le départ réel des marchandises.' : 'Mettez le commerçant au courant de l’avancement.'}</Text></View><Button icon="arrow-forward" loading={busy === 'transition'} disabled={!!busy} onPress={() => run('transition', () => post(`/admin/orders/${o.id}/transition`, { status: next[0] }), 'Étape enregistrée.')}>{next[1]}</Button></View> : null}
      {o.status === 'QUOTED' ? <Notice>Le commerçant doit accepter cette version du devis avant la confirmation. Aucun stock n’est réservé tant qu’il n’a pas accepté.</Notice> : null}
      {o.status === 'OUT_FOR_DELIVERY' ? <DeliveryEditor order={o} busy={busy} run={run} reportError={reportError} /> : null}
      {o.items.some((l: any) => l.refusedQuantity > (l.inspectedQuantity || 0)) ? <ReturnInspector order={o} busy={busy} run={run} reportError={reportError} /> : null}
      {['REQUESTED', 'QUOTED', 'SUBMITTED', 'CONFIRMED'].includes(o.status) ? <View style={S.panel}><SectionTitle title="Traiter une exception" detail="Un motif est enregistré et visible dans l’historique." />{!confirmAction ? <View style={[S.row, { flexWrap: 'wrap' }]}>{['REQUESTED', 'QUOTED', 'SUBMITTED'].includes(o.status) ? <Button variant="danger" onPress={() => setConfirmAction('REJECTED')}>Refuser la demande</Button> : null}{['SUBMITTED', 'CONFIRMED'].includes(o.status) ? <Button variant="secondary" onPress={() => setConfirmAction('CANCELLED')}>Annuler la commande</Button> : null}</View> : <View style={{ gap: 14 }}><Field label={confirmAction === 'REJECTED' ? 'Motif du refus' : 'Motif de l’annulation'} value={reason} onChangeText={setReason} multiline /><View style={S.row}><Button variant="danger" loading={busy === 'exception'} disabled={!reason.trim() || !!busy} onPress={() => run('exception', async () => { await post(`/admin/orders/${o.id}/transition`, { status: confirmAction, reason }); setConfirmAction(''); setReason(''); }, 'Décision enregistrée et réservations mises à jour.')}>Confirmer {confirmAction === 'REJECTED' ? 'le refus' : 'l’annulation'}</Button><Button variant="ghost" onPress={() => setConfirmAction('')}>Revenir</Button></View></View>}</View> : null}
    </> : tab === 'claims' ? <AdminClaims order={o} busy={busy} run={run} reportError={reportError} /> : tab === 'history' ? <View style={S.panel}><SectionTitle title="Le fil de la commande" detail="Événements enregistrés par le serveur" />{o.timeline.map((e: any, i: number) => <View key={e.id} style={{ flexDirection: 'row', gap: 15, paddingBottom: 24 }}><View style={{ alignItems: 'center', width: 18 }}><View style={{ width: 10, height: 10, borderRadius: 5, backgroundColor: i === o.timeline.length - 1 ? C.green : '#B7CBBF', marginTop: 4 }} />{i < o.timeline.length - 1 ? <View style={{ width: 1, backgroundColor: C.border, flex: 1, marginTop: 7, minHeight: 25 }} /> : null}</View><View style={{ flex: 1, gap: 4 }}><Text style={S.label}>{actionLabels[e.action] || statuses[e.action] || e.action}</Text><Text style={S.muted}>{e.details}</Text><Text style={S.small}>{e.actor} · {date(e.at, true)}</Text></View></View>)}</View> : <View style={{ gap: 20 }}>
      <View style={A.metricStrip}><SummaryValue label="Montant dû" value={money(o.balance.due)} icon="receipt-outline" /><SummaryValue label="Encaissé net" value={money(o.balance.collected)} icon="wallet-outline" positive /><SummaryValue label="Reste à encaisser" value={money(o.balance.remaining)} icon="time-outline" /></View>
      {o.balance.remaining > 0 && ['CONFIRMED', 'PREPARING', 'READY', 'OUT_FOR_DELIVERY', 'DELIVERED', 'PARTIALLY_DELIVERED', 'DELIVERY_REFUSED'].includes(o.status) ? <View style={S.panel}><SectionTitle title="Déclarer un encaissement réel" detail="La livraison ne crée pas automatiquement un paiement." /><View style={{ gap: 16 }}><View style={[S.row, { alignItems: 'flex-start', flexWrap: 'wrap' }]}><Field label="Montant reçu en DA" value={payment} onChangeText={setPayment} keyboardType="decimal-pad" placeholder="0,00" /><Field label="Référence ou reçu" value={reference} onChangeText={setReference} placeholder="Référence facultative" /></View><View style={S.row}><Chip active={method === 'CASH'} onPress={() => setMethod('CASH')}>Espèces</Chip><Chip active={method === 'TRANSFER'} onPress={() => setMethod('TRANSFER')}>Virement reçu</Chip></View><Button style={{ alignSelf: 'flex-start' }} loading={busy === 'payment'} disabled={!!busy} icon="wallet-outline" onPress={() => { try { const v = amount(payment, 'Montant reçu'); if (!v || v > o.balance.remaining) throw new Error('Le montant doit être positif et ne pas dépasser le solde.'); run('payment', async () => { await post(`/admin/orders/${o.id}/payments`, { amount: v, method, reference, idempotencyKey: paymentKey.current }); setPayment(''); setReference(''); paymentKey.current = operationKey(); }, 'Encaissement enregistré.'); } catch (e) { reportError(errText(e)); } }}>Enregistrer l’encaissement</Button></View></View> : null}
      {o.balance.refundDue > 0 ? <View style={S.panel}><SectionTitle title="Rembourser le trop-perçu" detail={`${money(o.balance.refundDue)} à restituer après la réception partielle ou le refus.`} /><View style={{ gap: 14 }}><Field label="Montant remboursé en DA" value={refund} onChangeText={setRefund} keyboardType="decimal-pad" /><Field label="Référence du remboursement" value={refundRef} onChangeText={setRefundRef} /><Field label="Motif" value={refundReason} onChangeText={setRefundReason} /><Button loading={busy === 'refund'} style={{ alignSelf: 'flex-start' }} onPress={() => { try { const n = amount(refund, 'Remboursement'); if (!n || n > o.balance.refundDue || !refundRef.trim() || !refundReason.trim()) throw new Error('Saisissez un montant dans la limite du trop-perçu, une référence et un motif.'); run('refund', async () => { await post(`/admin/orders/${o.id}/refunds`, { amount: n, reference: refundRef, reason: refundReason, idempotencyKey: refundKey.current }); setRefund(''); setRefundRef(''); setRefundReason(''); }, 'Remboursement enregistré.'); } catch (e) { reportError(errText(e)); } }}>Enregistrer le remboursement</Button></View></View> : null}
      <View style={S.panel}><SectionTitle title="Écritures de paiement" detail="Rapprochez uniquement une somme effectivement remise et vérifiée." />{o.payments.length ? o.payments.map((p: any) => <View key={p.id} style={[A.productRow, { flexWrap: 'wrap' }]}><Icon name={p.isRefund ? 'return-down-back-outline' : 'wallet-outline'} color={p.isRefund ? C.red : C.green} /><View style={{ flex: 1, minWidth: 150 }}><Text style={S.label}>{p.isRefund ? 'Remboursement' : p.method === 'CASH' ? 'Espèces reçues' : 'Virement reçu'} · {money(p.amount)}</Text><Text style={S.small}>{date(p.at, true)}{p.reference ? ` · ${p.reference}` : ''}</Text></View>{p.reconciled ? <Status value="RECONCILED" /> : <Button small variant="secondary" disabled={!!busy} loading={busy === p.id} onPress={() => run(p.id, () => post(`/admin/payments/${p.id}/reconcile`), 'Écriture rapprochée.')}>Rapprocher</Button>}</View>) : <Empty title="Aucun encaissement enregistré" message="Le montant dû reste distinct de l’argent réellement reçu." icon="wallet-outline" />}</View>
    </View>}
  </View>;
}

function QuoteEditor({ order: o, busy, run, reportError }: { order: any; busy: string; run: Run; reportError: (message: string) => void }) {
  const { width } = useWindowDimensions();
  const [lines, setLines] = useState<Record<string, { quantity: string; price: string; stock: string; pack: string }>>(() => Object.fromEntries(o.items.map((l: any) => [l.productId, { quantity: String(l.quantity ?? l.requestedQuantity), price: l.unitPrice == null ? '' : String(l.unitPrice), stock: '', pack: String(l.caseSize || 1) }])));
  const [fee, setFee] = useState(String(o.deliveryFee ?? '')), [validity, setValidity] = useState('48'), [note, setNote] = useState(o.adminNote || '');
  const update = (id: string, field: string, value: string) => setLines(v => ({ ...v, [id]: { ...v[id], [field]: value } }));
  const previewable = Object.values(lines).every(l => l.quantity.trim() && Number.isSafeInteger(Number(l.quantity)) && Number(l.quantity) >= 0 && (Number(l.quantity) === 0 || (l.price.trim() && Number.isFinite(Number(l.price.replace(',', '.'))) && Number(l.price.replace(',', '.')) > 0))) && fee.trim() && Number.isFinite(Number(fee.replace(',', '.'))) && Number(fee.replace(',', '.')) >= 0;
  const total = previewable ? Object.values(lines).reduce((v, l) => v + (Number(l.price.replace(',', '.')) || 0) * Number(l.quantity), 0) + Number(fee.replace(',', '.')) : null;
  const submit = () => { try { const parsed = o.items.map((l: any) => { const v = lines[l.productId], quantity = int(v.quantity, 'Quantité proposée', true), caseSize = int(v.pack, 'Colisage'); if (quantity && quantity % caseSize) throw new Error(`La quantité de ${l.name} doit être un multiple du colisage.`); const unitPrice = quantity ? amount(v.price, `Prix de ${l.name}`) : v.price.trim() ? amount(v.price, 'Prix') : 0; if (quantity && unitPrice <= 0) throw new Error('Les lignes disponibles doivent avoir un prix strictement positif.'); const availableStock = v.stock.trim() ? int(v.stock, 'Stock physique', true) : undefined; return { productId: l.productId, quantity, unitPrice, caseSize, ...(availableStock == null ? {} : { availableStock }) }; }); const hours = int(validity, 'Durée de validité'); if (hours > 720) throw new Error('La validité ne peut pas dépasser 30 jours, soit 720 heures.'); const deliveryFee = amount(fee, 'Frais de livraison'); run('quote', () => post(`/admin/orders/${o.id}/quote`, { items: parsed, deliveryFee, validUntil: new Date(Date.now() + hours * 3600000).toISOString(), note }), 'Devis envoyé au commerçant pour validation.'); } catch (e) { reportError(errText(e)); } };
  return <View style={S.panel}><SectionTitle title={o.status === 'QUOTED' ? 'Réviser la proposition' : 'Préparer le devis'} detail="Confirmez les vraies conditions de votre entreprise, ligne par ligne." /><Notice>Les quantités sont exprimées en unités de produit. Le prix est par unité. Le stock physique inclut les unités déjà réservées ; laissez-le vide uniquement si un stock est déjà confirmé. Une quantité proposée à zéro signale une rupture.</Notice><View style={{ marginTop: 20, gap: 4 }}>{o.items.map((l: any) => <View key={l.productId} style={{ paddingVertical: 18, borderBottomWidth: 1, borderColor: C.border, gap: 14 }}><View style={S.row}><ProductImage uri={l.imageUrl} name={l.name} size={54} /><View style={{ flex: 1 }}><Text style={S.text}>{l.name}</Text><Text style={S.small}>{l.brand} · {l.requestedQuantity} unités demandées</Text></View></View><View style={{ flexDirection: width >= 700 ? 'row' : 'column', gap: 12 }}><Field label="Quantité proposée" value={lines[l.productId].quantity} onChangeText={v => update(l.productId, 'quantity', v)} keyboardType="number-pad" /><Field label="Prix unitaire en DA" value={lines[l.productId].price} onChangeText={v => update(l.productId, 'price', v)} keyboardType="decimal-pad" placeholder="À confirmer" /><Field label="Unités par colis" value={lines[l.productId].pack} onChangeText={v => update(l.productId, 'pack', v)} keyboardType="number-pad" /><Field label="Stock physique total" value={lines[l.productId].stock} onChangeText={v => update(l.productId, 'stock', v)} keyboardType="number-pad" placeholder="Déjà confirmé ou à saisir" /></View></View>)}</View><View style={{ gap: 16, marginTop: 20 }}><View style={{ flexDirection: width >= 700 ? 'row' : 'column', gap: 14 }}><Field label="Frais de livraison en DA" value={fee} onChangeText={setFee} keyboardType="decimal-pad" /><Field label="Validité à partir de l’envoi en heures" value={validity} onChangeText={setValidity} keyboardType="number-pad" /></View><Field label="Note de la proposition" value={note} onChangeText={setNote} multiline placeholder="Disponibilité, précisions sur les formats ou la livraison…" /><View style={[S.between, { flexWrap: 'wrap' }]}><View><Text style={S.small}>Total proposé avec livraison</Text><Text style={S.subheading}>{total == null ? 'Renseignez les prix' : money(total)}</Text></View><Button icon="paper-plane-outline" loading={busy === 'quote'} disabled={!!busy} onPress={submit}>{o.status === 'QUOTED' ? 'Envoyer la nouvelle version' : 'Envoyer le devis'}</Button></View></View></View>;
}

function DeliveryEditor({ order: o, busy, run, reportError }: { order: any; busy: string; run: Run; reportError: (message: string) => void }) {
  const [accepted, setAccepted] = useState<Record<string, string>>(() => Object.fromEntries(o.items.map((l: any) => [l.productId, String(l.quantity)]))), [note, setNote] = useState(''), [confirm, setConfirm] = useState(false);
  const save = () => { try { const items = o.items.map((l: any) => { const qty = int(accepted[l.productId], 'Quantité acceptée', true); if (qty > l.quantity) throw new Error('La quantité acceptée ne peut pas dépasser la quantité expédiée.'); return { productId: l.productId, acceptedQuantity: qty, refusedQuantity: l.quantity - qty }; }); if (items.some((l: any) => l.refusedQuantity > 0) && !note.trim()) throw new Error('Précisez le motif des quantités refusées.'); run('delivery', () => post(`/admin/orders/${o.id}/delivery`, { items, note }), 'Réception enregistrée. Le paiement reste à vérifier séparément.'); } catch (e) { reportError(errText(e)); setConfirm(false); } };
  return <View style={S.panel}><SectionTitle title="Confirmer la réception réelle" detail="Les refus entrent en quarantaine jusqu’au contrôle physique du retour." />{o.items.map((l: any) => <View key={l.productId} style={[A.productRow, { flexWrap: 'wrap' }]}><Text style={[S.text, { flex: 1, minWidth: 180 }]}>{l.name}<Text style={S.small}>{`\n${l.quantity} unités expédiées`}</Text></Text><View style={{ width: 160 }}><Field label="Unités acceptées" value={accepted[l.productId]} onChangeText={v => { setAccepted(a => ({ ...a, [l.productId]: v })); setConfirm(false); }} keyboardType="number-pad" /></View><Text style={S.small}>{Math.max(0, l.quantity - (Number(accepted[l.productId]) || 0))} refusées</Text></View>)}<View style={{ gap: 14, marginTop: 16 }}><Field label="Note de réception et motif des refus" value={note} onChangeText={setNote} multiline /><Button icon="checkmark-done-outline" loading={busy === 'delivery'} disabled={!!busy} onPress={() => confirm ? save() : setConfirm(true)} style={{ alignSelf: 'flex-start' }}>{confirm ? 'Confirmer ces quantités reçues' : 'Vérifier puis enregistrer la réception'}</Button>{confirm ? <Notice>Vérifiez les quantités avec le commerçant avant de confirmer. Cet enregistrement fixe le montant dû sur les unités acceptées.</Notice> : null}</View></View>;
}
function ReturnInspector({ order: o, busy, run, reportError }: { order: any; busy: string; run: Run; reportError: (message: string) => void }) {
  const [productId, setProductId] = useState(o.items.find((l: any) => l.refusedQuantity > (l.inspectedQuantity || 0))?.productId || ''), [quantity, setQuantity] = useState(''), [disposition, setDisposition] = useState('RESTOCK'), [reason, setReason] = useState('');
  return <View style={S.panel}><SectionTitle title="Contrôler les retours en quarantaine" detail="Effectuez cette action après réception physique et contrôle de la marchandise." /><View style={{ gap: 16 }}><View style={{ gap: 8 }}>{o.items.filter((l: any) => l.refusedQuantity > (l.inspectedQuantity || 0)).map((l: any) => <Chip key={l.productId} active={productId === l.productId} onPress={() => setProductId(l.productId)}>{l.name} · {l.refusedQuantity - (l.inspectedQuantity || 0)} à contrôler</Chip>)}</View><Field label="Quantité contrôlée" value={quantity} onChangeText={setQuantity} keyboardType="number-pad" /><View style={[S.row, { flexWrap: 'wrap' }]}><Chip active={disposition === 'RESTOCK'} onPress={() => setDisposition('RESTOCK')}>Remettre en stock</Chip><Chip active={disposition === 'WRITE_OFF'} onPress={() => setDisposition('WRITE_OFF')}>Constater une perte</Chip></View><Field label="Motif et résultat du contrôle" value={reason} onChangeText={setReason} multiline /><Button disabled={!!busy} loading={busy === 'inspect'} style={{ alignSelf: 'flex-start' }} onPress={() => { try { const n = int(quantity, 'Quantité'); if (!productId || !reason.trim()) throw new Error('Sélectionnez le produit et précisez le résultat du contrôle.'); run('inspect', async () => { await post(`/admin/orders/${o.id}/returns/inspect`, { productId, quantity: n, disposition, reason }); setQuantity(''); setReason(''); }, 'Contrôle du retour enregistré.'); } catch (e) { reportError(errText(e)); } }}>Enregistrer le contrôle</Button></View></View>;
}

function ProductEditor({ product: p, busy, onClose, onSave, onAdjust, reportError }: { product: ManagedProduct; busy: string; onClose: () => void; onSave: (body: any) => Promise<void>; onAdjust: (body: any) => Promise<void>; reportError: (message: string) => void }) {
  const { width } = useWindowDimensions();
  const physical = p.physicalStock ?? p.onHand ?? (p.stock == null ? null : p.stock + (p.reserved || 0));
  const [price, setPrice] = useState(String(p.savedPrice ?? p.price ?? '')), [stock, setStock] = useState(String(physical ?? '')), [pack, setPack] = useState(String(p.savedCaseSize ?? p.caseSize ?? 1)), [minimum, setMinimum] = useState(String(p.minimumQuantity || 1)), [approved, setApproved] = useState(p.offerApproved), [active, setActive] = useState(p.isActive !== false), [delta, setDelta] = useState(''), [reason, setReason] = useState(''), [adjustOpen, setAdjustOpen] = useState(false);
  useEffect(() => { setStock(String(physical ?? '')); }, [physical]);
  const save = () => { try { const priceValue = price.trim() ? amount(price, 'Prix') : null, stockValue = stock.trim() ? int(stock, 'Stock', true) : null, caseSize = int(pack, 'Colisage'), min = int(minimum, 'Minimum'); if (min % caseSize) throw new Error('Le minimum doit être un multiple du nombre d’unités par colis.'); if (approved && (!priceValue || stockValue == null)) throw new Error('Une offre approuvée exige un prix positif et un stock physique confirmé.'); onSave({ price: priceValue, stock: stockValue, caseSize, minimumQuantity: min, offerApproved: approved, isActive: active }); } catch (e) { reportError(errText(e)); } };
  return <View style={[S.panel, { borderColor: C.border }]}><SectionTitle title="Conditions de vente" detail="L’identité du produit et son image restent liées à leur source." action={<Button icon="close" label="Fermer l’éditeur du produit" variant="ghost" onPress={onClose} />} /><View style={[S.row, { alignItems: 'flex-start', marginBottom: 20 }]}><ProductImage uri={p.imageUrl} name={p.name} size={95} /><View style={{ flex: 1, gap: 5 }}><Text style={S.subheading}>{p.name}</Text><Text style={S.muted}>{p.brand} · {p.barcode}</Text><Text style={S.small}>{p.unit || 'Format à vérifier'} · {p.category}</Text>{p.sourceUrl ? <Button variant="ghost" icon="open-outline" small style={{ alignSelf: 'flex-start', paddingLeft: 0 }} onPress={() => Linking.openURL(p.sourceUrl!).catch(e => reportError(errText(e)))}>Consulter la source produit</Button> : null}</View></View><View style={{ gap: 16 }}><Notice>Un prix public n’est pas votre prix de gros. Publiez uniquement les conditions que votre entreprise confirme. Prix par unité de produit ; stock physique total avant réservations.</Notice><View style={{ flexDirection: width >= 750 ? 'row' : 'column', gap: 14 }}><Field label="Prix unitaire en DA" value={price} onChangeText={setPrice} keyboardType="decimal-pad" placeholder="Inconnu si vide" /><Field label="Stock physique total" value={stock} onChangeText={setStock} keyboardType="number-pad" placeholder="Inconnu si vide" /><Field label="Unités par colis" value={pack} onChangeText={setPack} keyboardType="number-pad" /><Field label="Minimum de commande" value={minimum} onChangeText={setMinimum} keyboardType="number-pad" /></View><Text style={S.small}>{p.reserved || 0} unités réservées · {p.quarantined || 0} unités en quarantaine · {p.stock == null ? 'Disponible inconnu' : `${p.stock} disponibles`}</Text><View style={{ gap: 12 }}><View style={S.between}><View style={{ flex: 1 }}><Text style={S.label}>Offre de vente approuvée</Text><Text style={S.small}>Affiche le prix et autorise la commande directe si le stock le permet.</Text></View><Switch accessibilityLabel="Offre de vente approuvée" value={approved} onValueChange={setApproved} trackColor={{ false: '#CCD8CF', true: C.green }} thumbColor={C.white} /></View><View style={S.between}><View style={{ flex: 1 }}><Text style={S.label}>Référence active</Text><Text style={S.small}>Une référence suspendue reste conservée dans les historiques.</Text></View><Switch accessibilityLabel="Référence active" value={active} onValueChange={setActive} trackColor={{ false: '#CCD8CF', true: C.green }} thumbColor={C.white} /></View></View><View style={[S.between, { flexWrap: 'wrap' }]}><Button icon="save-outline" loading={busy === 'product'} disabled={!!busy} onPress={save}>Enregistrer les conditions</Button><Button variant="ghost" icon="add-circle-outline" onPress={() => setAdjustOpen(!adjustOpen)}>Ajuster le stock</Button></View>{adjustOpen ? <View style={{ borderTopWidth: 1, borderColor: C.border, paddingTop: 18, gap: 14 }}><Field label="Variation de stock en unités" value={delta} onChangeText={setDelta} keyboardType={Platform.OS === 'ios' ? 'numbers-and-punctuation' : 'numeric'} placeholder="Par exemple +12 ou -3 selon votre comptage" /><Field label="Motif de l’ajustement" value={reason} onChangeText={setReason} placeholder="Réception fournisseur, inventaire, casse…" /><Button variant="secondary" loading={busy === 'adjust'} disabled={!!busy} style={{ alignSelf: 'flex-start' }} onPress={() => { try { const n = Number(delta); if (!delta.trim() || !Number.isSafeInteger(n) || !n || !reason.trim()) throw new Error('Saisissez une variation entière non nulle et son motif.'); onAdjust({ delta: n, reason }); } catch (e) { reportError(errText(e)); } }}>Enregistrer l’ajustement</Button></View> : null}</View></View>;
}

